import { Effect, String } from "effect"

export interface MaintenanceWindow {
  readonly startsAt: string
  readonly endsAt: string
  readonly region: string
  readonly summary: string
}

export interface Mailer {
  readonly send: (message: {
    readonly to: string
    readonly subject: string
    readonly body: string
  }) => Effect.Effect<void>
}

export const sendMaintenanceNotice = Effect.fn("sendMaintenanceNotice")(
  function*(mailer: Mailer, recipient: string, window: MaintenanceWindow) {
    const summary = String.trim(window.summary)

    yield* mailer.send({
      to: recipient,
      subject: `Scheduled maintenance: ${window.region}`,
      body: String.stripMargin(`
      |# Scheduled maintenance
      |
      |We will update the storage cluster in ${window.region}.
      |The maintenance window runs from ${window.startsAt} to ${window.endsAt}.
      |
      |## Expected impact
      |${summary}
      |Existing downloads will continue without interruption.
      |New uploads may briefly return a retryable error.
      |
      |## Preparing your applications
      |- Keep automatic retries enabled.
      |- Use exponential backoff for failed uploads.
      |  Allow at least thirty seconds between repeated attempts.
      |- Check the status page before opening a support request.
      |
      |We will send another notice when maintenance is complete.
      `),
    })
  },
)
